        outputTypeKey: 'EXECUTIVE_BRIEF',
        runtimeStateWrites: expect.objectContaining({
          status: 'NOT_WRITTEN',
          reason: 'NO_REVIEWED_GRR_RUNTIME_PATH_V1',
        }),
